customize.css:
/* Same-origin only: system fonts, no imports, no images from elsewhere. Mobile first. */
:root {
	--bg: #ffffff;
	--surface: #f3f4f8;
	--fg: #14161a;
	--muted: #4a5060;
	--link: #1d4ed8;
	--accent: #4c1d95;
	--accent-fg: #ffffff;
	--border: #c7cad6;
	--focus: #b45309;
	--stale-bg: #fff4d6;
	--stale-fg: #5a3b00;
	--demo-bg: #e9eaf2;
	--demo-fg: #2d3142;
	--deriv-bg: #dff3e4;
	--deriv-fg: #0d4a22;
	color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {

	:root {
		--bg: #101218;
		--surface: #1a1d27;
		--fg: #eceef4;
		--muted: #b4b9c9;
		--link: #8fb4ff;
		--accent: #c4b5fd;
		--accent-fg: #14102a;
		--border: #3a3f52;
		--focus: #fbbf24;
		--stale-bg: #3a2c05;
		--stale-fg: #ffe3a3;
		--demo-bg: #2a2e3f;
		--demo-fg: #dfe2ee;
		--deriv-bg: #123a22;
		--deriv-fg: #c9f1d6;
	}

}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
	margin: 0;
	background: var(--bg);
	color: var(--fg);
	font: 1rem/1.6 system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

a { color: var(--link); text-underline-offset: 0.15em; }

:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 2px; }

.skip { position: absolute; left: -999px; top: 0; background: var(--bg); color: var(--fg); padding: 0.5rem 1rem; z-index: 10; }
.skip:focus { left: 0; }

header.site {
	display: flex;
	flex-wrap: wrap;
	align-items: baseline;
	justify-content: space-between;
	gap: 0.25rem 1.5rem;
	padding: 0.75rem 1rem;
	border-bottom: 1px solid var(--border);
}

.brand { font-weight: 700; font-size: 1.15rem; color: var(--fg); text-decoration: none; }
header.site nav { display: flex; gap: 1.25rem; }
header.site nav a { color: var(--fg); padding: 0.4rem 0; }

main { max-width: 64rem; margin: 0 auto; padding: 1rem 1rem 3rem; }
footer.site { border-top: 1px solid var(--border); padding: 1rem; color: var(--muted); font-size: 0.9rem; max-width: 64rem; margin: 0 auto; }

h1 { font-size: 1.75rem; line-height: 1.2; margin: 0.5rem 0 0.5rem; }
h2 { font-size: 1.35rem; line-height: 1.25; margin: 2rem 0 0.5rem; }
h3 { font-size: 1.1rem; line-height: 1.3; margin: 1.25rem 0 0.4rem; }
p, ul, ol, dl { margin: 0.5rem 0; }
code { font-size: 0.9em; background: var(--surface); padding: 0.05em 0.3em; border-radius: 3px; overflow-wrap: anywhere; }
pre { background: var(--surface); padding: 0.75rem 1rem; border-radius: 6px; overflow-x: auto; }
pre code { background: none; padding: 0; }
.small { font-size: 0.9rem; color: var(--muted); }
.lede { font-size: 1.15rem; }
.meta { color: var(--muted); font-size: 0.95rem; margin: 0.25rem 0; }
.crumb { color: var(--muted); font-size: 0.9rem; margin: 0; }

.badge { display: inline-block; font-size: 0.8rem; font-weight: 600; padding: 0.05rem 0.5rem; border-radius: 999px; }
.badge-demonstration { background: var(--demo-bg); color: var(--demo-fg); }
.badge-derivation { background: var(--deriv-bg); color: var(--deriv-fg); }

.intro { max-width: 44rem; }
.legend { color: var(--muted); font-size: 0.95rem; }

/* index */
.cards { list-style: none; padding: 0; display: grid; gap: 1.25rem; grid-template-columns: 1fr; }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; height: 100%; display: flex; flex-direction: column; }
.card-poster { display: block; aspect-ratio: 16 / 9; background: var(--border); }
.card-poster img { display: block; width: 100%; height: 100%; object-fit: cover; }
.card-body { padding: 0.75rem 1rem 1rem; display: flex; flex-direction: column; flex: 1; }
.card h3 { margin: 0 0 0.25rem; }
.card h3 a { color: var(--fg); }
.card .claim { margin: 0.5rem 0; }
.ships { margin: auto 0 0; padding-top: 0.5rem; font-size: 0.95rem; }
.ships-label { color: var(--muted); }
.open-scene { font-weight: 700; }

@media (min-width: 40rem) {
	.cards { grid-template-columns: repeat(2, 1fr); }
	h1 { font-size: 2.2rem; }
}

@media (min-width: 62rem) {
	.cards { grid-template-columns: repeat(3, 1fr); }
}

/* entry */
.player video { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; background: #000; border-radius: 6px; }
.note { color: var(--muted); }

.open-the-scene {
	margin: 1.5rem 0;
	padding: 1rem 1.25rem 1.25rem;
	border: 3px solid var(--accent);
	border-radius: 10px;
	background: var(--surface);
}
.open-the-scene h2 { margin-top: 0; }

.button {
	display: inline-block;
	padding: 0.85rem 1.4rem;
	background: var(--accent);
	color: var(--accent-fg);
	font-weight: 700;
	font-size: 1.1rem;
	text-decoration: none;
	border-radius: 8px;
	border: 2px solid var(--accent);
}
.button:hover { filter: brightness(1.1); }
.button.secondary { background: transparent; color: var(--fg); border-color: var(--fg); font-size: 1rem; }

.claim-text { font-size: 1.2rem; }
.assumptions li, .transcript li { margin: 0.3rem 0; }
.transcript { padding-left: 0; list-style: none; max-width: 44rem; }
.transcript li { display: flex; gap: 0.75rem; }
.ts { flex: none; min-width: 3rem; font-variant-numeric: tabular-nums; }
.colours dt { font-weight: 700; margin-top: 0.5rem; }
.colours dd { margin: 0 0 0 1rem; }

.stale { background: var(--stale-bg); color: var(--stale-fg); border: 2px solid var(--stale-fg); border-radius: 6px; padding: 0.75rem 1rem; }

.prose { max-width: 44rem; }
.prose li { margin: 0.35rem 0; }

@media (prefers-reduced-motion: reduce) {
	* { transition: none !important; animation: none !important; }
}

.transcript .cue-link { margin-left: .4em; text-decoration: none; opacity: .6; }
.transcript .cue-link:hover, .transcript .cue-link:focus { opacity: 1; }
.transcript li:target { background: rgba(127, 127, 127, .15); }

.wrap{max-width:none;margin:0;padding:0}.wrap>main{max-width:64rem;margin:0 auto;padding:1rem 1rem 3rem}.posts:empty{display:none}article[data-page]>h1{display:none}.entry-header{margin-bottom:1rem}.card img{margin:0;border-radius:0}.card-body h3{margin:0 0 .25rem}.card-poster img{max-width:none}h1,h2,h3{letter-spacing:normal}footer.site{line-height:1.6}header.site{margin:0}.home{margin:0}main>article{margin:0}.entry{margin:0}

#reader{
   width:90%;
margin:auto;
}
